@app.post("/api/services/{service_id}/execute")
async def execute_service(service_id: str, payload: dict):
    """Execute a specific scientific service"""
    service = service_registry.get_service(service_id)
    if not service:
        raise HTTPException(status_code=404, detail="Szolgáltatás nem található")

    # For now, return a simulated execution result
    return {
        "service_id": service_id,
        "service_name": service["name"],
        "status": "completed",
        "result": f"Szolgáltatás '{service['name']}' sikeresen végrehajtva",
        "execution_time": "2.3s",
        "timestamp": datetime.now().isoformat()
    }

@app.get("/manifest.json")
async def get_manifest():
    """Serve PWA manifest"""
    with open("static/manifest.json", "r", encoding="utf-8") as f:
        return JSONResponse(content=json.load(f))

@app.exception_handler(Exception)
async def global_exception_handler(request: Request, exc: Exception):
    """Global exception handler"""
    logger.error(f"Unhandled exception: {str(exc)}")
    logger.error(traceback.format_exc())
    return JSONResponse(
        status_code=500,
        content={"detail": "Belső szerver hiba történt"}
    )

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=5000)

