"""
AI Client Manager for JADED Deep Discovery AI Platform
Handles Cerebras, Gemini, OpenAI, and Anthropic integrations
"""

import os
import asyncio
import logging
from typing import Dict, Any, Optional, AsyncGenerator
import json

# AI Client imports
from cerebras.cloud.sdk import Cerebras
try:
    from google import genai
    from google.genai import types
except ImportError:
    genai = None
    types = None
import openai
import anthropic
from anthropic import Anthropic

logger = logging.getLogger(__name__)

class AIClientManager:
    """
    Centralized manager for all AI client integrations
    """

    def __init__(self):
        self.cerebras_client = None
        self.gemini_client = None
        self.openai_client = None
        self.anthropic_client = None
        self.initialized = False

    async def initialize(self):
        """Initialize all AI clients"""
        try:
            # Initialize Cerebras client with updated model
            cerebras_api_key = os.environ.get("CEREBRAS_API_KEY")
            if cerebras_api_key:
                self.cerebras_client = Cerebras(api_key=cerebras_api_key)
                logger.info("Cerebras client initialized with gpt-oss-120b support")

            # Initialize Gemini client with new google-genai library
            gemini_api_key = os.environ.get("GEMINI_API_KEY")
            if gemini_api_key and genai:
                self.gemini_client = genai.Client(api_key=gemini_api_key)
                logger.info("Gemini 2.5 Pro client initialized")
            elif gemini_api_key:
                logger.warning("Gemini library not available")

            # Initialize OpenAI client
            openai_api_key = os.environ.get("OPENAI_API_KEY")
            if openai_api_key:
                self.openai_client = openai.OpenAI(api_key=openai_api_key)
                logger.info("OpenAI client initialized")

            # Initialize Anthropic client
            anthropic_api_key = os.environ.get("ANTHROPIC_API_KEY")
            if anthropic_api_key:
                self.anthropic_client = Anthropic(api_key=anthropic_api_key)
                logger.info("Anthropic client initialized")

            self.initialized = True
            logger.info("All AI clients initialized successfully")

        except Exception as e:
            logger.error(f"Error initializing AI clients: {str(e)}")

    async def get_status(self) -> Dict[str, bool]:
        """Get status of all AI clients"""
        return {
            "cerebras": self.cerebras_client is not None,
            "gemini": self.gemini_client is not None,
            "openai": self.openai_client is not None,
            "anthropic": self.anthropic_client is not None,
            "initialized": self.initialized
        }

    async def chat(self, message: str, model: str) -> Dict[str, Any]:
        """
        Send a chat message to the specified model
        """
        try:
            if "gpt-oss-120b" in model or "cerebras" in model.lower():
                return await self._cerebras_chat(message, model)
            elif "gemini" in model.lower():
                return await self._gemini_chat(message, model)
            elif "gpt" in model.lower() or "openai" in model.lower():
                return await self._openai_chat(message, model)
            elif "claude" in model.lower() or "anthropic" in model.lower():
