"""
AI Client Manager for JADED Deep Discovery AI Platform
Handles Cerebras, Gemini, OpenAI, and Anthropic integrations
"""

import os
import asyncio
import logging
from typing import Dict, Any, Optional, AsyncGenerator
import json

# AI Client imports
from cerebras.cloud.sdk import Cerebras
try:
    from google import genai
    from google.genai import types
except ImportError:
    genai = None
    types = None
import openai
import anthropic
from anthropic import Anthropic

logger = logging.getLogger(__name__)

class AIClientManager:
    """
    Centralized manager for all AI client integrations
    """

    def __init__(self):
        self.cerebras_client = None
        self.gemini_client = None
        self.openai_client = None
        self.anthropic_client = None
        self.initialized = False

    async def initialize(self):
        """Initialize all AI clients"""
        try:
            # Initialize Cerebras client with updated model
            cerebras_api_key = os.environ.get("CEREBRAS_API_KEY")
            if cerebras_api_key:
                self.cerebras_client = Cerebras(api_key=cerebras_api_key)
                logger.info("Cerebras client initialized with gpt-oss-120b support")

            # Initialize Gemini client with new google-genai library
            gemini_api_key = os.environ.get("GEMINI_API_KEY")
            if gemini_api_key and genai:
                self.gemini_client = genai.Client(api_key=gemini_api_key)
                logger.info("Gemini 2.5 Pro client initialized")
            elif gemini_api_key:
                logger.warning("Gemini library not available")

            # Initialize OpenAI client
            openai_api_key = os.environ.get("OPENAI_API_KEY")
            if openai_api_key:
                self.openai_client = openai.OpenAI(api_key=openai_api_key)
                logger.info("OpenAI client initialized")

            # Initialize Anthropic client
            anthropic_api_key = os.environ.get("ANTHROPIC_API_KEY")
            if anthropic_api_key:
                self.anthropic_client = Anthropic(api_key=anthropic_api_key)
                logger.info("Anthropic client initialized")

            self.initialized = True
            logger.info("All AI clients initialized successfully")

        except Exception as e:
            logger.error(f"Error initializing AI clients: {str(e)}")

    async def get_status(self) -> Dict[str, bool]:
        """Get status of all AI clients"""
        return {
            "cerebras": self.cerebras_client is not None,
            "gemini": self.gemini_client is not None,
            "openai": self.openai_client is not None,
            "anthropic": self.anthropic_client is not None,
            "initialized": self.initialized
        }

    async def chat(self, message: str, model: str) -> Dict[str, Any]:
        """
        Send a chat message to the specified model
        """
        try:
            if "gpt-oss-120b" in model or "cerebras" in model.lower():
                return await self._cerebras_chat(message, model)
            elif "gemini" in model.lower():
                return await self._gemini_chat(message, model)
            elif "gpt" in model.lower() or "openai" in model.lower():
                return await self._openai_chat(message, model)
            elif "claude" in model.lower() or "anthropic" in model.lower():
                return await self._anthropic_chat(message, model)
            else:
                # Default to Cerebras gpt-oss-120b
                return await self._cerebras_chat(message, "gpt-oss-120b")

        except Exception as e:
            logger.error(f"Chat error with model {model}: {str(e)}")
            raise

    async def stream_chat(self, message: str, model: str) -> AsyncGenerator[str, None]:
        """
        Stream a chat response from the specified model
        """
        try:
            if "gpt-oss-120b" in model or "cerebras" in model.lower():
                async for chunk in self._cerebras_stream(message, model):
                    yield chunk
            elif "gemini" in model.lower():
                async for chunk in self._gemini_stream(message, model):
                    yield chunk
            elif "gpt" in model.lower() or "openai" in model.lower():
                async for chunk in self._openai_stream(message, model):
                    yield chunk
            elif "claude" in model.lower() or "anthropic" in model.lower():
                async for chunk in self._anthropic_stream(message, model):
                    yield chunk
            else:
                # Default to Cerebras gpt-oss-120b
                async for chunk in self._cerebras_stream(message, "gpt-oss-120b"):
                    yield chunk

        except Exception as e:
            logger.error(f"Stream error with model {model}: {str(e)}")
            yield f"data: {json.dumps({'error': str(e)})}\n\n"

    async def _cerebras_chat(self, message: str, model: str) -> Dict[str, Any]:
        """Handle Cerebras chat requests"""
        if not self.cerebras_client:
            raise Exception("Cerebras client not initialized")

        try:
            # Use gpt-oss-120b as the default/main model
            if model in ["gpt-oss-120b", "cerebras"]:
                model_name = "gpt-oss-120b"
                config = {
                    "max_tokens": 65536,
                    "temperature": 1,
                    "top_p": 1
                }
            else:
                # Fallback configurations for other models
                model_name = model
                config = {
                    "max_tokens": 40000,
                    "temperature": 0.23,
                    "top_p": 0.05
                }

            response = self.cerebras_client.chat.completions.create(
                messages=[{"role": "user", "content": message}],
                model=model_name,
                max_tokens=config["max_tokens"],
                temperature=config["temperature"],
                top_p=config["top_p"]
            )

            if hasattr(response, 'choices') and response.choices:
                return {
                    "response": response.choices[0].message.content,
                    "model": model_name,
                    "provider": "cerebras",
                    "status": "success"
                }
            else:
                raise Exception("Invalid response from Cerebras")

        except Exception as e:
            logger.error(f"Cerebras chat error: {str(e)}")
            raise

    async def _cerebras_stream(self, message: str, model: str) -> AsyncGenerator[str, None]:
        """Handle Cerebras streaming chat requests"""
        if not self.cerebras_client:
            raise Exception("Cerebras client not initialized")

        try:
            # Use gpt-oss-120b as the default model
            if model in ["gpt-oss-120b", "cerebras"]:
                model_name = "gpt-oss-120b"
                config = {
                    "max_tokens": 65536,
                    "temperature": 1,
                    "top_p": 1
                }
            else:
                model_name = model
                config = {
                    "max_tokens": 40000,
                    "temperature": 0.23,
                    "top_p": 0.05
                }

            stream = self.cerebras_client.chat.completions.create(
                messages=[{"role": "user", "content": message}],
                model=model_name,
                stream=True,
                max_tokens=config["max_tokens"],
                temperature=config["temperature"],
                top_p=config["top_p"]
            )

            for chunk in stream:
                if hasattr(chunk, 'choices') and chunk.choices and len(chunk.choices) > 0:
                    if hasattr(chunk.choices[0], 'delta') and chunk.choices[0].delta and hasattr(chunk.choices[0].delta, 'content') and chunk.choices[0].delta.content:
                        yield f"data: {json.dumps({'content': chunk.choices[0].delta.content})}\n\n"

        except Exception as e:
            logger.error(f"Cerebras stream error: {str(e)}")
            yield f"data: {json.dumps({'error': str(e)})}\n\n"

    async def _gemini_chat(self, message: str, model: str) -> Dict[str, Any]:
        """Handle Gemini chat requests with new google-genai library"""
        if not self.gemini_client:
            raise Exception("Gemini client not initialized")

        try:
            # Use Gemini 2.5 Pro
            model_name = "gemini-2.5-pro"

            response = self.gemini_client.models.generate_content(
                model=model_name,
                contents=message
            )

            return {
                "response": response.text,
                "model": model_name,
                "provider": "gemini",
                "status": "success"
            }

        except Exception as e:
            logger.error(f"Gemini chat error: {str(e)}")
            raise

    async def _gemini_stream(self, message: str, model: str) -> AsyncGenerator[str, None]:
        """Handle Gemini streaming chat requests"""
        if not self.gemini_client:
            raise Exception("Gemini client not initialized")

        try:
            model_name = "gemini-2.5-pro"

            stream = self.gemini_client.models.generate_content_stream(
                model=model_name,
                contents=message
            )

            for chunk in stream:
                if chunk.text:
                    yield f"data: {json.dumps({'content': chunk.text})}\n\n"

        except Exception as e:
            logger.error(f"Gemini stream error: {str(e)}")
            yield f"data: {json.dumps({'error': str(e)})}\n\n"

    async def _openai_chat(self, message: str, model: str) -> Dict[str, Any]:
        """Handle OpenAI chat requests"""
        if not self.openai_client:
            raise Exception("OpenAI client not initialized")

        try:
            # the newest OpenAI model is "gpt-4o" which was released May 13, 2024.
            # do not change this unless explicitly requested by the user
            model_name = "gpt-4o" if model == "openai" else model

            response = self.openai_client.chat.completions.create(
                model=model_name,
                messages=[{"role": "user", "content": message}],
                max_tokens=4000
            )

            return {
                "response": response.choices[0].message.content,
                "model": model_name,
                "provider": "openai",
                "status": "success"
            }

        except Exception as e:
            logger.error(f"OpenAI chat error: {str(e)}")
            raise

    async def _openai_stream(self, message: str, model: str) -> AsyncGenerator[str, None]:
        """Handle OpenAI streaming chat requests"""
        if not self.openai_client:
            raise Exception("OpenAI client not initialized")

        try:
            model_name = "gpt-4o" if model == "openai" else model

            stream = self.openai_client.chat.completions.create(
                model=model_name,
                messages=[{"role": "user", "content": message}],
                stream=True,
                max_tokens=4000
            )

            for chunk in stream:
                if hasattr(chunk, 'choices') and chunk.choices and len(chunk.choices) > 0:
                    if hasattr(chunk.choices[0], 'delta') and chunk.choices[0].delta and hasattr(chunk.choices[0].delta, 'content') and chunk.choices[0].delta.content:
                        yield f"data: {json.dumps({'content': chunk.choices[0].delta.content})}\n\n"

        except Exception as e:
            logger.error(f"OpenAI stream error: {str(e)}")
            yield f"data: {json.dumps({'error': str(e)})}\n\n"

    async def _anthropic_chat(self, message: str, model: str) -> Dict[str, Any]:
        """Handle Anthropic chat requests"""
        if not self.anthropic_client:
            raise Exception("Anthropic client not initialized")

        try:
            # The newest Anthropic model is "claude-sonnet-4-20250514", not "claude-3-5-sonnet-20241022" nor "claude-3-sonnet-20240229"
            model_name = "claude-sonnet-4-20250514" if model == "anthropic" else model

            response = self.anthropic_client.messages.create(
                model=model_name,
                max_tokens=4000,
                messages=[{"role": "user", "content": message}]
            )

            return {
                "response": response.content[0].text,
                "model": model_name,
                "provider": "anthropic",
                "status": "success"
            }

        except Exception as e:
            logger.error(f"Anthropic chat error: {str(e)}")
            raise

    async def _anthropic_stream(self, message: str, model: str) -> AsyncGenerator[str, None]:
        """Handle Anthropic streaming chat requests"""
        if not self.anthropic_client:
            raise Exception("Anthropic client not initialized")

        try:
            model_name = "claude-sonnet-4-20250514" if model == "anthropic" else model

            stream = self.anthropic_client.messages.create(
                model=model_name,
                max_tokens=4000,
                messages=[{"role": "user", "content": message}],
                stream=True
            )

            for chunk in stream:
                if chunk.type == "content_block_delta" and hasattr(chunk.delta, 'text'):
                    yield f"data: {json.dumps({'content': chunk.delta.text})}\n\n"

        except Exception as e:
            logger.error(f"Anthropic stream error: {str(e)}")
            yield f"data: {json.dumps({'error': str(e)})}\n\n"

