"""
Database models for JADED Deep Discovery AI Platform
"""

from sqlalchemy import Column, Integer, String, Text, DateTime, Float, Boolean, JSON
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.sql import func
from datetime import datetime

Base = declarative_base()

class ChatSession(Base):
    __tablename__ = "chat_sessions"

    id = Column(Integer, primary_key=True, index=True)
    session_id = Column(String(255), unique=True, index=True)
    model_used = Column(String(100))
    message_count = Column(Integer, default=0)
    created_at = Column(DateTime, default=func.now())
    updated_at = Column(DateTime, default=func.now(), onupdate=func.now())

class ChatMessage(Base):
    __tablename__ = "chat_messages"

    id = Column(Integer, primary_key=True, index=True)
    session_id = Column(String(255), index=True)
    role = Column(String(20))  # 'user' or 'assistant'
    content = Column(Text)
    model_used = Column(String(100))
    tokens_used = Column(Integer)
    response_time = Column(Float)
    created_at = Column(DateTime, default=func.now())

class AlphaFoldPrediction(Base):
    __tablename__ = "alphafold_predictions"

    id = Column(Integer, primary_key=True, index=True)
    run_id = Column(String(255), unique=True, index=True)
    sequence = Column(Text)
    status = Column(String(50))  # 'pending', 'running', 'completed', 'failed'
    confidence_metrics = Column(JSON)
    structure_data = Column(Text)  # PDB string or file path
    execution_time = Column(Float)
    created_at = Column(DateTime, default=func.now())
    completed_at = Column(DateTime)

class ServiceExecution(Base):
    __tablename__ = "service_executions"

    id = Column(Integer, primary_key=True, index=True)
    service_id = Column(String(255), index=True)
    service_name = Column(String(255))
    input_data = Column(JSON)
    output_data = Column(JSON)
    status = Column(String(50))
    execution_time = Column(Float)
    created_at = Column(DateTime, default=func.now())

class UserSession(Base):
    __tablename__ = "user_sessions"

    id = Column(Integer, primary_key=True, index=True)
